     "title": "法国血液中心确认受 11 月 2 日黑客升温攻击波及，幸无实际影响",
     "url": "https://www.ithome.com/1/022/461.htm",
     "time": "11-04 23:02",
     "ts": 1793804524,
     "summary": "IT之家 11 月 4 日消息，法国公共血液服务机构法国血液中心 (EFS) 当地时间本月 3 日发布声明确认，其三个场地的冷库监控与控制系统由于供应商的关系成为本月 2 日黑客“升温攻击”的间接目标。这些冷库中保存着待交付给医疗机构的制品以及供内部生物样本库使用的样本。幸运的是，该机构的监控和报警系统迅速识别出了这些异常情况并采取了必要措施，没有任何样本或血液制品受到影响。涉事设备已被及时控制或停用，原本存放在这三个冷库的物资已被转移到其它设施。相关阅读：《欧洲多国超市遭黑",
     "source": "IT之家",
