     "title": "IPO要暂停了？求证：并非“一刀切”",
     "url": "https://www.huxiu.com/article/4903072.html",
     "time": "11-04 22:10",
     "ts": 1793801439,
     "summary": "本文来自微信公众号： 财联社 ，作者：赵昕睿近日，有关监管对投行进行“非正式”窗口指导、暂停IPO的传闻持续发酵，引发市场高度关注。记者向多位业内人士了解到，部分券商接收到会放慢甚至暂停IPO进程的安排，但大概率是收紧而非“一刀切”。有业内人士透露，该举措与近期二级市场表现不容乐观有关。若结合最近一轮阶段性收紧IPO节奏的举措来看，证监会于2023年8月27日便表示，根据彼时市场情况，阶段性收紧IPO节奏，促进投融资两端的动态平衡。今年9月也传出过IPO收紧传闻，只不过指向机",
