     "time": "11-04 23:21",
     "ts": 1793805695,
     "summary": "11月3日，丹麦自治领地格陵兰岛议会投票批准了一份美国、丹麦及其自治领地格陵兰岛之间的安全协议。因格陵兰岛自治政府与反对党之间的争议，当天的会议一度中断。 今年9月，美国总统特朗普、丹麦首相弗雷泽里克森、格陵兰岛自治政府总理延斯-弗雷德里克·尼尔森签署了这份协议。这份协议为美国进一步扩大在格陵兰岛的军事存在铺平道路。协议的相关安排让格陵兰岛民众感到担忧和无助。（文章来源：CCTV国际时讯）",
