     "title": "透视医疗器械三季报：海外市场成“必争之地”，部分厂商海外营收已超国内",
     "url": "http://finance.eastmoney.com/news/1354,202611043922329457.html",
     "time": "11-04 23:21",
     "ts": 1793805671,
     "summary": "随着A股医疗器械公司2026年三季报披露基本收官（奥精医疗因故延期），行业经营格局逐步清晰：超七成企业实现营收增长，但利润修复尚未覆盖多数标的，各细分赛道景气度分化明显。 据《每日经济新闻》记者（以下简称每经记者）梳理，按申万二级行业分类，已披露三季报的141家医疗器械上市公司前三季度合计营收2015.44亿元，同比增长8.73%，七成以上公司营收实现正增长。不过利润端拐点尚未在多数企业兑现，141家公司中，扣非后归母净利润同比增长的企业不足半数，41家企业出现“增收不增利”",
