     "time": "11-04 22:34",
     "ts": 1793802848,
     "summary": "美国财政部悄然修改债券发行前瞻指引，删除一个关键措辞，为2027年起削减长期国债发行量打开大门。这是财政部长贝森特（Scott Bessent）一系列压制长端收益率举措的最新动作。 周三，财政部在季度再融资声明中宣布，未来数个季度将维持名义附息债券及浮息票据拍卖规模不变，但删去了自2024年初以来一直沿用的&#34;至少&#34;（at least）一词。这一细微措辞变化意味着，财政部已预留空间，最早可于2027年对长期债券发行规模进行下调。 就市场影响而言，此举是贝森特在过",
