     "summary": "美国私营部门就业市场在10月延续增长势头。 当地时间周三，ADP公布的数据显示，美国10月私营部门新增就业人数8.6万人，与经下修后的9月数据基本持平，高于市场预期的6.7万人，显示劳动力市场出现企稳迹象。 从行业分布来看，就业增长主要来自服务业。其中，贸易、运输和公用事业新增3.9万个岗位，教育和医疗服务新增2.8万个，休闲和酒店业新增1.9万个。金融活动、建筑业及其他服务业也实现增长，分别新增1.5万、1.3万和1万个岗位。 不过，部分行业就业人数出现下降。专业和商业服务",
