     "title": "A股一日反弹可否延续？12家基金公司拆解三大推手",
     "url": "http://stock.eastmoney.com/news/11215,202611043922213178.html",
     "time": "11-04 21:10",
     "ts": 1793797809,
     "summary": "A股午后突然放量拉升，科技股成为反弹主力。 市场为何在午后突然转向？财联社记者采访的12家基金公司将此次反弹的原因集中在三方面：一是美国中期选举结果逐渐明朗，外部不确定性阶段性释放，市场风险偏好回升；二是国内稳市政策接连落地，回购增持再贷款、互换便利及ETF资金形成支撑；三是科技股此前跌幅较深，估值和筹码压力得到释放，半导体、算力等产业链的业绩和订单预期又为反弹提供了支撑。 从午后盘面来看，半导体、存储、CPO等科技方向率先拉升，并带动主要指数走强，银行、白酒等防御板块则相对",
