     "time": "11-04 21:02",
     "ts": 1793797377,
     "summary": "市场震荡中，私募业绩普遍承压，不少知名管理人旗下产品净值跌破1元，成了“毛基”。 但斌执掌的东方港湾旗下东方港湾宏远2期私募证券投资基金的最新净值报告显示，截至10月30日，该基金单位净值跌至约0.63元。私募排排网数据显示，同期，私募大V、嘉越投资基金经理吴悦风管理的产品净值更是跌至0.55元，今年以来最大回撤超70%。另外，多家头部量化私募旗下产品也出现了“7毛基”。 渠道人士透露，10月以来市场波动加剧，尤其是科技板块回撤明显，在此背景下，重仓科技或者风格暴露相对激进的",
